using System;using System.IO;using System.IO.Compression;using System.Threading.Tasks;
class UpdateTests{
 static int n;static void Ok(bool x,string message){if(!x)throw new Exception(message);Console.WriteLine("PASS "+message);n++;}static void Reject(Action f,string message){try{f();}catch{Ok(true,message);return;}throw new Exception(message);}
 static void Zip(string path,string prefix,bool evil){using(var z=ZipFile.Open(path,ZipArchiveMode.Create)){foreach(string name in new[]{"YuriMusic-YouTube.exe","YuriMusicUpdater.exe","web/index.html"}){var entry=z.CreateEntry(prefix+"/"+name);using(var writer=new StreamWriter(entry.Open()))writer.Write("test");}if(evil){var entry=z.CreateEntry(prefix+"/../../outside.txt");using(var writer=new StreamWriter(entry.Open()))writer.Write("bad");}}}
 static void Main(){try{Run().GetAwaiter().GetResult();}catch(Exception e){Console.WriteLine(e);Environment.ExitCode=1;}}
 static async Task Run(){string root=Path.Combine(Environment.CurrentDirectory,"work","updater-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Ok(AppUpdates.ParseVersion("v0.10.0")>AppUpdates.ParseVersion("0.9.0"),"numeric version comparison");Reject(()=>AppUpdates.ParseVersion("v1.0.0-beta"),"reject prerelease version");Ok(!AppUpdates.Allowed(new Uri("https://example.com/update.zip"))&&!AppUpdates.Allowed(new Uri("http://github.com/update.zip")),"restrict update download origins");string hash=new string('a',64);Ok(AppUpdates.ExpectedHash(hash+"  app.zip\n","app.zip")==hash,"parse checksum");Reject(()=>AppUpdates.ExpectedHash(hash+"  other.zip","app.zip"),"reject missing asset checksum");string zip=Path.Combine(root,"good.zip");Zip(zip,"YuriMusic-Windows-0.8.0",false);string source=Path.Combine(root,"source");AppUpdates.Extract(zip,source,"YuriMusic-Windows-0.8.0");Ok(File.Exists(Path.Combine(source,"web","index.html")),"extract valid update");string bad=Path.Combine(root,"bad.zip");Zip(bad,"YuriMusic-Windows-0.8.0",true);Reject(()=>AppUpdates.Extract(bad,Path.Combine(root,"invalid"),"YuriMusic-Windows-0.8.0"),"reject zip traversal");string target=Path.Combine(root,"installed");Directory.CreateDirectory(target);File.WriteAllText(Path.Combine(target,"YuriMusic-YouTube.exe"),"old");File.WriteAllText(Path.Combine(target,"web"),"block");Reject(()=>UpdaterMain.Apply(source,target,Path.Combine(root,"rollback")),"copy failure rolls back");Ok(File.ReadAllText(Path.Combine(target,"YuriMusic-YouTube.exe"))=="old","original executable restored");File.Delete(Path.Combine(target,"web"));UpdaterMain.Apply(source,target,Path.Combine(root,"backup"));Ok(File.ReadAllText(Path.Combine(target,"YuriMusic-YouTube.exe"))=="test","apply update successfully");var result=await new AppUpdates().Check();Console.WriteLine(new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(result));Ok(result!=null,"real GitHub release check");Console.WriteLine(n+" updater tests passed");}
}
